Code.Terraform:
```hcl
# SageMaker Feature Group with a KMS-encrypted offline store
resource "aws_sagemaker_feature_group" "<example_resource_name>" {
  feature_group_name             = "<example_resource_name>"
  record_identifier_feature_name = "<record_id>"
  event_time_feature_name        = "<event_time>"
  role_arn                       = "<example_resource_arn>"

  feature_definition {
    feature_name = "<record_id>"
    feature_type = "String"
  }

  feature_definition {
    feature_name = "<event_time>"
    feature_type = "String"
  }

  offline_store_config {
    s3_storage_config {
      s3_uri     = "s3://<bucket>/<prefix>"
      kms_key_id = "<example_resource_arn>" # Critical: encrypts the offline store with a customer-managed key
    }
  }
}
```
